const PlasmicDescendants = {
  root: [
    "root",
    "services",
    "cms",
    "h3",
    "p",
    "webDevelopmentServices",
    "uiUxDesign",
    "iOsDevelopment",
    "aiPipeline",
    "different",
    "steps",
    "comparison",
    "benefits",
    "successStories",
    "img"
  ],
  services: ["services"],
  cms: ["cms", "h3", "p"],
  h3: ["h3"],
  p: ["p"],
  webDevelopmentServices: ["webDevelopmentServices"],
  uiUxDesign: ["uiUxDesign"],
  iOsDevelopment: ["iOsDevelopment"],
  aiPipeline: ["aiPipeline"],
  different: ["different"],
  steps: ["steps"],
  comparison: ["comparison"],
  benefits: ["benefits"],
  successStories: ["successStories"],
  img: ["img"]
} as const;
type NodeNameType = keyof typeof PlasmicDescendants;
type DescendantsType<T extends NodeNameType> =
  (typeof PlasmicDescendants)[T][number];
type NodeDefaultElementType = {
  root: "div";
  services: "div";
  cms: "div";
  h3: "h3";
  p: "p";
  webDevelopmentServices: "div";
  uiUxDesign: "div";
  iOsDevelopment: "div";
  aiPipeline: "div";
  different: "div";
  steps: "div";
  comparison: "div";
  benefits: "div";
  successStories: "div";
  img: typeof PlasmicImg__;
};

type ReservedPropsType = "variants" | "args" | "overrides";
type NodeOverridesType<T extends NodeNameType> = Pick<
  PlasmicCard__OverridesType,
  DescendantsType<T>
>;
type NodeComponentProps<T extends NodeNameType> =
  // Explicitly specify variants, args, and overrides as objects
  {
    variants?: PlasmicCard__VariantsArgs;
    args?: PlasmicCard__ArgsType;
    overrides?: NodeOverridesType<T>;
  } &
    // Specify variants directly as props
    Omit<PlasmicCard__VariantsArgs, ReservedPropsType> &
    // Specify args directly as props
    Omit<PlasmicCard__ArgsType, ReservedPropsType> &
    // Specify overrides for each element directly as props
    Omit<
      NodeOverridesType<T>,
      ReservedPropsType | VariantPropType | ArgPropType
    > &
    // Specify props for the root element
    Omit<
      Partial<React.ComponentProps<NodeDefaultElementType[T]>>,
      ReservedPropsType | VariantPropType | ArgPropType | DescendantsType<T>
    >;

function makeNodeComponent<NodeName extends NodeNameType>(nodeName: NodeName) {
  type PropsType = NodeComponentProps<NodeName> & { key?: React.Key };
  const func = function <T extends PropsType>(
    props: T & StrictProps<T, PropsType>
  ) {
    const { variants, args, overrides } = React.useMemo(
      () =>
        deriveRenderOpts(props, {
          name: nodeName,
          descendantNames: PlasmicDescendants[nodeName],
          internalArgPropNames: PlasmicCard__ArgProps,
          internalVariantPropNames: PlasmicCard__VariantProps
        }),
      [props, nodeName]
    );
    return PlasmicCard__RenderFunc({
      variants,
      args,
      overrides,
      forNode: nodeName
    });
  };
  if (nodeName === "root") {
    func.displayName = "PlasmicCard";
  } else {
    func.displayName = `PlasmicCard.${nodeName}`;
  }
  return func;
}

export const PlasmicCard = Object.assign(
  // Top-level PlasmicCard renders the root element
  makeNodeComponent("root"),
  {
    // Helper components rendering sub-elements
    services: makeNodeComponent("services"),
    cms: makeNodeComponent("cms"),
    h3: makeNodeComponent("h3"),
    p: makeNodeComponent("p"),
    webDevelopmentServices: makeNodeComponent("webDevelopmentServices"),
    uiUxDesign: makeNodeComponent("uiUxDesign"),
    iOsDevelopment: makeNodeComponent("iOsDevelopment"),
    aiPipeline: makeNodeComponent("aiPipeline"),
    different: makeNodeComponent("different"),
    steps: makeNodeComponent("steps"),
    comparison: makeNodeComponent("comparison"),
    benefits: makeNodeComponent("benefits"),
    successStories: makeNodeComponent("successStories"),
    img: makeNodeComponent("img"),

    // Metadata about props expected for PlasmicCard
    internalVariantProps: PlasmicCard__VariantProps,
    internalArgProps: PlasmicCard__ArgProps
  }
);

export default PlasmicCard;
